{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table prd_db.justherbs.dwh_justherbs_unicommerce_fact_items as SELECT * FROM ( SELECT \"Shipping Address Pincode\" AS shipping_pincode, \"Billing Address Pincode\" AS billing_pincode, \"Channel Name\" AS marketplace, \"Channel Name\" AS source, \"Display Order Code\" AS order_id, \"Display Order Code\" AS reference_code, \"Shipping Address Phone\" AS phone, \"Billing Address Name\" AS name, \"Notification Email\" AS email, upper(category) AS category, TO_CHAR( TO_TIMESTAMP(NULLIF(updated, \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) AS SHIPPING_LAST_UPDATE_DATE, \"Item SKU Code\" AS sku, \"Seller SKU Code\" AS Marketplace_sku, \"Channel Product Id\" AS product_id, coalesce(\"Item Type Name\", \"SKU Name\") AS product_name, currency, coalesce(\"Shipping Address City\", \"Billing Address City\") AS city, coalesce(\"Shipping Address State\", \"Billing Address State\") AS state, CASE WHEN NOT (\"Sale Order Status\" IN (\'COMPLETE\', \'CANCELLED\')) AND \"Shipping Package Status Code\" IS NULL THEN \'UNFULFILLABLE\' ELSE \"Sale Order Status\" END AS order_status, \"Invoice Code\" AS invoice_code, TO_CHAR( TO_TIMESTAMP(NULLIF(\"Invoice Created\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) AS invoice_date, TO_CHAR( TO_TIMESTAMP(NULLIF(\"Order Date as dd/mm/yyyy hh:MM:ss\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) AS order_date, TO_CHAR( TO_TIMESTAMP(NULLIF(\"Shipping Package Creation Date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) AS shipping_package_creation_date, CAST(\"Shipping Charges\" AS double precision) AS shipping_price, 1 AS suborder_quantity, CAST(discount AS double precision) AS discount, try_CAST(\"Tax Value\" AS double precision) AS tax, try_CAST(\"Selling Price\" AS double precision) AS selling_price, \"Shipping Package Code\" AS shippingPackageCode, \"Shipping Package Status Code\" AS shippingPackageStatus, replace(\"Sale Order Item Code\",\'`\',\'\') AS SaleOrderItemCode, replace(\"Sale Order Item Code\",\'`\',\'\') AS Sales_Order_Item_ID, \"Tracking Number\" AS AWB, facility AS Warehouse_Name, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Mode, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Method, \"Shipping Courier\" AS Courier, \"Shipping Courier Status\" AS shipping_status, \"Shipping Tracking Status\" AS shipping_tracking_status, 1 AS shippedQuantity, TO_CHAR( TO_TIMESTAMP(NULLIF(\"Dispatch Date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) AS dispatch_date, TO_CHAR( TO_TIMESTAMP(NULLIF(\"EWayBill Date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) AS ewaybill_date, TO_CHAR( TO_TIMESTAMP(NULLIF(\"Delivery Time\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) AS delivery_date, TO_CHAR( TO_TIMESTAMP(NULLIF(\"Return Date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) AS return_date, TO_CHAR( TO_TIMESTAMP(NULLIF(\"Reverse Pickup Created Date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) AS reverse_pickup_date, TO_CHAR( TO_TIMESTAMP(NULLIF(\"Fulfillment TAT\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) AS fulfillment_tat, \"Reverse Pickup Code\" AS reverse_pickup_code, \"Return Remarks\" AS return_remarks, \"Reverse Pickup Reason\" AS reverse_pickup_reason, CASE WHEN \"Return Date\" IS NOT NULL AND TRIM(CAST(\"Return Date\" AS varchar)) <> \'\' AND LOWER(TRIM(CAST(\"Return Date\" AS varchar))) <> \'null\' THEN 1 ELSE 0 END AS return_flag, CASE WHEN \"Return Date\" IS NOT NULL AND TRIM(CAST(\"Return Date\" AS varchar)) <> \'\' AND LOWER(TRIM(CAST(\"Return Date\" AS varchar))) <> \'null\' THEN 1 ELSE 0 END AS return_quantity, CASE WHEN \"Return Date\" IS NOT NULL AND TRIM(CAST(\"Return Date\" AS varchar)) <> \'\' AND LOWER(TRIM(CAST(\"Return Date\" AS varchar))) <> \'null\' THEN CAST(\"Selling Price\" AS double precision) ELSE 0 END AS return_sales, CASE WHEN lower(\"Sale Order Status\") LIKE \'%cancel%\' OR lower(\"Shipping Courier Status\") LIKE \'%cancel%\' THEN 1 ELSE 0 END AS cancelled_quantity, row_number() OVER ( PARTITION BY \"Display Order Code\", \"Sale Order Item Code\" ORDER BY TO_CHAR( TO_TIMESTAMP(NULLIF(updated, \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) DESC ) AS rw FROM datalake_db.justherbs.trn_unicommerce_get_sale_orders fi ) t WHERE rw = 1;",
                    "transaction": true
                }
            ) }}
